if __name__=='__main__':
    rows=[]
    for r in reports:
        verdict,repair,edit_spec,route,score,evidence,reply=C[r['reportId']]
        edit=dict(zip(('field','find','replace'),edit_spec)) if edit_spec else None
        rows.append({'reportId':r['reportId'],'questionId':r['questionId'],'verdict':verdict,'repair':repair,'edit':edit,'route':route,'confidence':score,'evidence':evidence,'student_reply':reply})
    rows.sort(key=lambda x:x['reportId'])
    (ROOT/'results.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(f'Wrote manually curated, untested static demo results ({len(rows)} reports)')
